#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Mise en ligne de J2 (#111) : vérifications à la main sur un aperçu local du site, qui lit la vraie DGMR dans le
# navigateur comme en ligne, puis publication du site et suivi de la sonde DGMR sur une journée. Rien n'est publié ni
# commenté sans un « y » à la question. Aucune réponse de la DGMR n'entre dans le dépôt (norme DCG 8401) : le relevé
# du jour reste dans TRAVAIL.
#
#   scripts/mise-en-ligne-j2.sh           toutes les étapes, depuis la première
#   scripts/mise-en-ligne-j2.sh 12        reprendre à l'étape 12 (le suivi de la sonde, le lendemain par exemple)
#   scripts/mise-en-ligne-j2.sh liste     la liste des étapes
#
# Variables : TRAVAIL (relevé du jour, journaux et notes de la relecture, hors du dépôt), PORT (aperçu local, 4173).

ETAPES=(
  "prealables|Préalables : J2 dans main, outils, PR #112"
  "apercu|Construire le site et lancer l'aperçu local"
  "releve|Rattachement réel : répartition des restrictions du jour"
  "echantillon|Rattachement réel : 10 restrictions relues sur la carte"
  "carte|Carte : sortes, tirets, à venir, zooms, contour, avec Permis"
  "bureau|Volet, onglet Routes et fiche sur bureau"
  "mobile|Volet, onglet Routes et fiche sur mobile"
  "heures|Heures réelles : une fermeture de nuit contre vd.ch"
  "lien_mort|Lien mort réel : le ?r= d'une restriction levée"
  "pages|Pages : À propos, Couverture, Protection des données, <head>"
  "publication|Publier le site"
  "sonde|Sonde réelle : suivi sur une journée"
  "bilan|Bilan et commentaire sur #111"
)
TOTAL_STAGES=${#ETAPES[@]}

DEPOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
WEB="$DEPOT/web"
TRAVAIL="${TRAVAIL:-${XDG_STATE_HOME:-$HOME/.local/state}/vigie-vaud/mise-en-ligne-j2}"
NOTES="$TRAVAIL/notes.md"
ENV_FILE="$TRAVAIL/valeurs.env"   # `ask` y cherche ses valeurs par défaut ; rien n'y est écrit
PORT="${PORT:-4173}"
LOCAL="http://localhost:$PORT"
TICKET=111
PR=112
FUSION_J2=7349df92eb0c33eefc396054e81c5b931f3073fb
REPO_CODE=Louni-M/vigie-vaud
REPO_DONNEES=Louni-M/vigie-vaud-donnees
SITE=https://louni-m.github.io/vigie-vaud
PAGES_DONNEES=https://louni-m.github.io/vigie-vaud-donnees
VD_RESTRICTIONS=https://www.vd.ch/mobilite/loffre-de-mobilite-a-votre-disposition/transports-individuels-motorises-tim/restrictions-de-circulation-et-travaux
mkdir -p "$TRAVAIL"

# ── Outils des étapes ─────────────────────────────────────────────────────

# lancer CMD… affiche la commande, puis la lance.
lancer() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; "$@"; }
arreter() { printf '\n'; warn "$1"; note "Reprendre avec : scripts/mise-en-ligne-j2.sh $_STAGE_INDEX"; exit 1; }
noter() { printf -- '- %s · %s\n' "$(date '+%F %R')" "$1" >> "$NOTES"; }
# valider "question" : y, ou bien une remarque notée pour la suite.
valider() {
  if confirm "$1"; then
    noter "OK · $1"
  else
    ask REMARQUE "Ce qui ne va pas (noté dans $NOTES) :"
    noter "À REPRENDRE · $1 · ${REMARQUE:-sans précision}"
    warn "noté ; à reprendre avant la publication si c'est bloquant"
  fi
}
suite() { printf '\n'; pause "Entrée : étape suivante"; }
ok() { printf '  %s✓ %s%s\n' "$GREEN" "$1" "$RESET"; }

# L'aperçu local : le site construit, servi par `vite preview`. Celui que ce script lance s'arrête avec lui.
APERCU_PID=""
arreter_apercu() { if [[ -n "$APERCU_PID" ]]; then kill "$APERCU_PID" 2>/dev/null || true; APERCU_PID=""; fi; }
trap arreter_apercu EXIT
apercu_repond() { curl -fsS -o /dev/null "$LOCAL/" 2>/dev/null; }
# apercu_pret : l'aperçu répond, lancé au besoin sur le site déjà construit (étape 2).
apercu_pret() {
  apercu_repond && return 0
  [[ -f "$WEB/build/index.html" ]] || arreter "site non construit : reprendre à l'étape 2"
  note "Aperçu local : $LOCAL (journal $TRAVAIL/apercu.log)"
  (cd "$WEB" && exec ./node_modules/.bin/vite preview --port "$PORT" --strictPort) > "$TRAVAIL/apercu.log" 2>&1 &
  APERCU_PID=$!
  local i
  for i in {1..30}; do apercu_repond && return 0; sleep 1; done
  arreter "l'aperçu ne répond pas : voir $TRAVAIL/apercu.log"
}

# releve : lit toute la DGMR (596 en cours, 595 à venir, sans emprise, comme le site) et rattache chaque restriction
# par le `rattacher` du site, sur les limites publiées avec lui. Tourne dans Vitest, qui résout `$app` et `#lib`.
# Écrit dans TRAVAIL, rien n'en sort : rapport.txt, repartition.txt, echantillon.tsv, nuit.tsv, morts.tsv,
# communes.tsv et ids-<jour>.tsv (les OBJECTID vus, pour trouver un lien mort les jours suivants).
releve() {
  cat > "$TRAVAIL/releve.test.ts" <<'TS'
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { test } from 'vitest';

const { WEB, TRAVAIL, LOCAL } = process.env as Record<string, string>;
const R = `${WEB}/src/lib/couches/routes`;
const { rattacher } = await import(`${R}/rattachement.ts`);
const { sorteDe } = await import(`${R}/sortes.ts`);
const { ligneHoraires, periode, leveeLeWeekEnd } = await import(`${R}/horaires.ts`);
const { CHAMPS } = await import(`${R}/dgmr.ts`);
const { MAPSERVER, PAGE, aUneSuite } = await import(`${WEB}/src/lib/api.ts`);

// Restrictions citées par la recherche des 17 et 18 octobre 2026 (docs/recherche/source-dgmr.md), et la commune où
// ouvrir leur lien quand elle est connue.
const DE_LA_RECHERCHE: Record<number, string> = Object.fromEntries(
	[4368, 5212, 5243, 5340, 5341, 5342, 5343, 10042, 10353, 10356, 10662, 10663, 10664, 10665, 10666, 10672]
		.map((id) => [id, 'lausanne'])
		.concat([[5031, 'chavannes-de-bogis'], [10046, 'nyon'], [10047, 'nyon']])
);

type Props = Record<string, string | number | null>;
type Entite = { properties: Props; geometry: unknown };

async function couche(n: number): Promise<Entite[]> {
	const toutes: Entite[] = [];
	for (let offset = 0; ; offset += PAGE) {
		const p = new URLSearchParams({
			where: '1=1',
			outFields: CHAMPS.join(','),
			orderByFields: 'OBJECTID',
			outSR: '4326',
			geometryPrecision: '6',
			resultOffset: String(offset),
			resultRecordCount: String(PAGE),
			f: 'geojson'
		});
		const r = await fetch(`${MAPSERVER}/${n}/query?${p}`);
		if (!r.ok) throw new Error(`${n} : HTTP ${r.status}`);
		const j = await r.json();
		if (j.error) throw new Error(`${n} : ${JSON.stringify(j.error)}`);
		toutes.push(...(j.features ?? []));
		if (!aUneSuite(j)) return toutes;
	}
}

const texte = (v: unknown) => (v == null || String(v).trim() === '' ? null : String(v).trim());
const aujourdhui = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Zurich' }).format(new Date());
const tsv = (lignes: string[][]) => lignes.map((l) => l.join('\t') + '\n').join('');

test('relevé', async () => {
	const communes = JSON.parse(readFileSync(`${WEB}/static/communes.json`, 'utf8'));
	const limites = JSON.parse(readFileSync(`${WEB}/static/communes-limites.json`, 'utf8'));
	const cs = communes.map((commune: { bfs: number }) => ({ commune, limites: limites[commune.bfs] ?? [] }));

	const vus = new Set<number>();
	const toutes = [];
	let sansTrace = 0;
	for (const [etat, n] of [['en cours', 596], ['à venir', 595]] as const)
		for (const { properties: p, geometry } of await couche(n)) {
			const id = Number(p.OBJECTID);
			if (vus.has(id)) continue;
			vus.add(id);
			if (!geometry) {
				sansTrace++;
				continue;
			}
			const passages: { commune: { nom: string; slug: string }; metres: number }[] = rattacher(geometry, cs);
			toutes.push({ id, etat, p, deviation: sorteDe(texte(p.RESTRICTION)) === 'deviation', passages });
		}
	type R = (typeof toutes)[number];

	const repartition = (rs: R[]) => {
		const c = [0, 0, 0, 0];
		for (const r of rs) c[r.passages.length === 0 ? 3 : Math.min(r.passages.length, 3) - 1]++;
		return c;
	};
	const ligne = (nom: string, total: number, c: number[]) =>
		`  ${nom.padEnd(18)}${String(total).padStart(8)}${c.map((x) => String(x).padStart(11)).join('')}`;
	const groupes: [string, R[]][] = [
		['Tous', toutes],
		['Hors déviations', toutes.filter((r) => !r.deviation)],
		['Déviations', toutes.filter((r) => r.deviation)]
	];
	const recherche: [string, number, number[]][] = [
		['Tous', 50, [33, 6, 11, 0]],
		['Hors déviations', 32, [28, 2, 2, 0]],
		['Déviations', 18, [5, 4, 9, 0]]
	];
	const entete = `  ${''.padEnd(18)}${'tracés'.padStart(8)}${['1 commune', '2', '3 ou plus', 'aucune'].map((h) => h.padStart(11)).join('')}`;
	const record = toutes.reduce((a, b) => (b.passages.length > a.passages.length ? b : a), toutes[0]);
	const enCours = toutes.filter((r) => r.etat === 'en cours').length;
	writeFileSync(
		`${TRAVAIL}/rapport.txt`,
		[
			`Relevé du ${aujourdhui} : ${toutes.length} restrictions avec un tracé (${enCours} en cours, ` +
				`${toutes.length - enCours} à venir)${sansTrace ? `, et ${sansTrace} sans tracé, écartées par le site` : ''}.`,
			'',
			'Le site, aujourd’hui :',
			entete,
			...groupes.map(([nom, rs]) => ligne(nom, rs.length, repartition(rs))),
			'',
			'La recherche, les 17 et 18 octobre 2026 :',
			entete,
			...recherche.map(([nom, total, c]) => ligne(nom, total, c)),
			'',
			record ? `Le plus de communes : ${decrire(record)}` : ''
		].join('\n') + '\n'
	);
	writeFileSync(
		`${TRAVAIL}/repartition.txt`,
		groupes.map(([nom, rs]) => `${nom} ${rs.length} : ${repartition(rs).join(' / ')}`).join(' ; ') + '\n'
	);

	function decrire(r: R) {
		const route = texte(r.p.RHRC);
		const communes = r.passages.map((x) => `${x.commune.nom} ${Math.round(x.metres)} m`).join(', ');
		return `#${r.id} · ${r.etat} · ${texte(r.p.RESTRICTION) ?? 'Autre'} · ${texte(r.p.NOM) ?? '(sans nom)'}` +
			`${route ? ` · ${route}` : ''} → ${communes || 'aucune commune'}`;
	}
	const lien = (r: R) => `${LOCAL}/commune/${r.passages[0].commune.slug}?r=${r.id}`;
	const rattachees = toutes.filter((r) => r.passages.length > 0);

	// 10 au hasard, dont au moins 3 qui parcourent plusieurs communes quand il y en a.
	const melange = <T>(xs: T[]) => xs.map((x) => [Math.random(), x] as const).sort((a, b) => a[0] - b[0]).map(([, x]) => x);
	const plusieurs = melange(rattachees.filter((r) => r.passages.length > 1)).slice(0, 3);
	const echantillon = [...plusieurs, ...melange(rattachees.filter((r) => !plusieurs.includes(r)))].slice(0, 10);
	writeFileSync(`${TRAVAIL}/echantillon.tsv`, tsv(melange(echantillon).map((r) => [lien(r), decrire(r)])));

	// Fermetures de nuit : HEURE_* remplies, et une plage qui passe minuit.
	const nuit = rattachees.filter((r) => {
		const [a, b] = [texte(r.p.HEURE_DEBUT), texte(r.p.HEURE_FIN)];
		return a && b && b < a;
	});
	writeFileSync(
		`${TRAVAIL}/nuit.tsv`,
		tsv(
			nuit.map((r) => {
				const d = {
					dateDebut: Number(r.p.DATE_DEBUT),
					dateFin: Number(r.p.DATE_FIN),
					heureDebut: texte(r.p.HEURE_DEBUT),
					heureFin: texte(r.p.HEURE_FIN)
				};
				const horaires = [ligneHoraires(d), periode(d, 'longue'), leveeLeWeekEnd(texte(r.p.WEEK_END))];
				const remarque = (texte(r.p.REMARQUE) ?? '').replace(/\s+/g, ' ');
				return [lien(r), decrire(r), horaires.filter(Boolean).join(' · '), remarque];
			})
		)
	);

	// La commune qui a le plus de restrictions (pour l'onglet Routes), et une qui n'en a aucune.
	const parCommune = new Map<string, number>();
	for (const r of rattachees) for (const x of r.passages) parCommune.set(x.commune.slug, (parCommune.get(x.commune.slug) ?? 0) + 1);
	const [chargee = ["lausanne", 0]] = [...parCommune].sort((a, b) => b[1] - a[1]);
	const vide = communes.find((c: { slug: string }) => !parCommune.has(c.slug));
	writeFileSync(`${TRAVAIL}/communes.tsv`, tsv([[chargee[0], `${chargee[1]} restrictions`], [vide.slug, 'aucune restriction']]));

	// Liens morts : les OBJECTID vus avant (relevés des jours précédents, recherche) que la DGMR ne publie plus.
	const anciens = new Map<number, [string, string]>();
	for (const [id, slug] of Object.entries(DE_LA_RECHERCHE)) anciens.set(Number(id), [slug, 'cité par la recherche du 17.10.2026']);
	for (const f of readdirSync(TRAVAIL).filter((f) => /^ids-\d{4}-\d{2}-\d{2}\.tsv$/.test(f)).sort())
		for (const l of readFileSync(`${TRAVAIL}/${f}`, 'utf8').split('\n').filter(Boolean)) {
			const [id, slug] = l.split('\t');
			anciens.set(Number(id), [slug, `vu le ${f.slice(4, 14)}`]);
		}
	const morts = [...anciens].filter(([id]) => !vus.has(id));
	writeFileSync(`${TRAVAIL}/morts.tsv`, tsv(morts.map(([id, [slug, vu]]) => [`${LOCAL}/commune/${slug}?r=${id}`, `#${id}, ${vu}`])));

	const fichier = `${TRAVAIL}/ids-${aujourdhui}.tsv`;
	const duJour = new Map<string, string>();
	if (existsSync(fichier))
		for (const l of readFileSync(fichier, 'utf8').split('\n').filter(Boolean)) duJour.set(l.split('\t')[0], l.split('\t')[1]);
	for (const r of rattachees) duJour.set(String(r.id), r.passages[0].commune.slug);
	writeFileSync(fichier, tsv([...duJour]));
}, 120_000);
TS
  note "Relevé de la DGMR (596 et 595), rattaché par le site : journal $TRAVAIL/releve.log"
  if ! (cd "$WEB" && export WEB TRAVAIL LOCAL && pnpm exec vitest run --dir "$TRAVAIL" "$TRAVAIL/releve.test.ts") \
       > "$TRAVAIL/releve.log" 2>&1; then
    tail -n 30 "$TRAVAIL/releve.log"
    arreter "le relevé a échoué : voir $TRAVAIL/releve.log"
  fi
}

# ── 1 ─────────────────────────────────────────────────────────────────────
etape_prealables() {
  say "Les vérifications portent sur le code de main, qui contient J2 (fusion de la PR #$PR)."
  local manque=0 outil
  for outil in git gh pnpm curl python3; do
    command -v "$outil" >/dev/null 2>&1 || { warn "$outil introuvable"; manque=1; }
  done
  (( manque == 0 )) || arreter "installer les outils manquants"
  gh auth status >/dev/null 2>&1 || arreter "gh n'est pas connecté : gh auth login"

  lancer git -C "$DEPOT" fetch --quiet origin
  git -C "$DEPOT" merge-base --is-ancestor "$FUSION_J2" HEAD \
    || arreter "HEAD ne contient pas la fusion de J2 : git switch main && git pull"
  if git -C "$DEPOT" diff --quiet origin/main HEAD -- web sources.json schema \
     && [[ -z "$(git -C "$DEPOT" status --porcelain -- web sources.json schema)" ]]; then
    ok "web/, sources.json et schema/ identiques à origin/main ($(git -C "$DEPOT" log -1 --format=%h origin/main))"
  else
    warn "web/, sources.json ou schema/ diffèrent de origin/main : l'aperçu ne sera pas le site publié"
    git -C "$DEPOT" diff --stat origin/main -- web sources.json schema | tail -n 5
  fi

  say ""
  say "PR #$PR :"
  gh pr view "$PR" -R "$REPO_CODE" --json state,mergedAt,title -q '"  \(.state) le \(.mergedAt) · \(.title)"'
  gh pr checks "$PR" -R "$REPO_CODE" 2>/dev/null | sed 's/^/  /' || true
  noter "PR #$PR : $(gh pr view "$PR" -R "$REPO_CODE" --json state,mergedAt -q '"\(.state) le \(.mergedAt)"')"

  say ""
  say "Dernière publication du site (avant J2, s'il n'a pas été republié depuis) :"
  gh run list -R "$REPO_CODE" --workflow publier.yml -L 1 | sed 's/^/  /' || true

  say ""
  lancer pnpm --dir "$WEB" install --frozen-lockfile --reporter=silent
  note "Notes de la relecture : $NOTES"
  suite
}

# ── 2 ─────────────────────────────────────────────────────────────────────
etape_apercu() {
  say "Le site construit comme en production, mais servi à la racine (BASE_PATH vide) : $LOCAL."
  say "Il ne contient aucune donnée de la DGMR : le navigateur interroge lui-même ogc.vd.ch, comme en ligne."
  arreter_apercu
  apercu_repond && arreter "$LOCAL répond déjà : arrêter ce serveur, ou choisir un autre PORT"
  # web/static/data : les données CAMAC de la version initiale, ignorées par git (absentes en CI) et lues par rien.
  # Vite copie static/ dans le site construit, que verifier-sans-rediffusion.sh refuserait à juste titre.
  local ancienne="$WEB/static/data"
  if [[ -e "$ancienne" ]]; then
    warn "$ancienne existe ($(du -sh "$ancienne" | cut -f1)) : les données de la version initiale, ignorées par git"
    note "Elles finiraient dans web/build/data, que la vérification refuse (norme DCG 8401). Rien ne les lit plus."
    local rangee; rangee="$TRAVAIL/static-data-$(date +%Y%m%d-%H%M%S)"
    confirm "Les déplacer dans $rangee (rien n'est supprimé) ?" || arreter "déplacer ou supprimer $ancienne, puis reprendre"
    lancer mv "$ancienne" "$rangee"
    noter "web/static/data déplacé dans $rangee"
  fi
  note "Journal : $TRAVAIL/build.log"
  printf '  %s$ BASE_PATH= pnpm build%s\n' "$DIM" "$RESET"
  if ! (cd "$WEB" && BASE_PATH='' pnpm build) > "$TRAVAIL/build.log" 2>&1; then
    tail -n 20 "$TRAVAIL/build.log"
    arreter "la construction a échoué : voir $TRAVAIL/build.log"
  fi
  ok "site construit"
  lancer "$DEPOT/.github/scripts/verifier-sans-rediffusion.sh" "$WEB/build"
  apercu_pret
  ok "aperçu prêt : $LOCAL"
  note "Il reste lancé jusqu'à la fin du script (ou Ctrl-C)."
  suite
}

# ── 3 ─────────────────────────────────────────────────────────────────────
etape_releve() {
  say "Toutes les restrictions du jour, rattachées par le site (seuil de 20 m), contre la répartition de la"
  say "recherche (50 tracés : 33 / 6 / 11). Le relevé reste dans $TRAVAIL, hors du dépôt."
  say ""
  releve
  sed 's/^/  /' "$TRAVAIL/rapport.txt"
  say ""
  step "Même allure : surtout 1 commune hors déviations, plusieurs pour les déviations, aucune à « aucune »."
  note "Les restrictions changent chaque jour : on compare l'allure, pas les nombres."
  noter "Rattachement du jour : $(cat "$TRAVAIL/repartition.txt")"
  valider "La répartition du rattachement est comparable à celle de la recherche ?"
  suite
}

# ── 4 ─────────────────────────────────────────────────────────────────────
etape_echantillon() {
  [[ -s "$TRAVAIL/echantillon.tsv" ]] || releve
  apercu_pret
  say "10 restrictions du jour, dont 3 sur plusieurs communes, ouvertes une à une. Pour chacune :"
  step "la fiche s'ouvre dans la première commune annoncée ;"
  step "sur la carte, le tracé parcourt bien les communes annoncées (la plus longue part d'abord) ;"
  step "une commune qu'il ne fait que longer n'y est pas."
  local i=0 url description
  while IFS=$'\t' read -r -u 3 url description; do
    i=$((i + 1))
    printf '\n  %s%d/10%s %s\n' "$BOLD" "$i" "$RESET" "$description"
    open_url "$url"
    valider "Rattachement de ${description%% ·*} juste ?"
  done 3< "$TRAVAIL/echantillon.tsv"
  suite
}

# ── 5 ─────────────────────────────────────────────────────────────────────
etape_carte() {
  apercu_pret
  open_url "$LOCAL/"
  say "La carte, couche Routes active (elle l'est par défaut)."
  say ""
  step "Une couleur par sorte, comme la légende du volet : Fermeture rouge, Déviation orange, Feux jaune,"
  step "Restriction particulière violet, Autres gris."
  valider "Couleur par sorte juste ?"
  step "Déviations en tirets ; à venir plus pâles ; en cours dessinées au-dessus de l'à venir là où elles se croisent."
  valider "Tirets, à venir plus pâle, en cours au-dessus : justes ?"
  step "Dézoomer jusqu'au canton (sous le zoom 11) : un point au milieu de chaque restriction, sauf les déviations."
  step "Rezoomer : les points disparaissent, les tracés restent."
  valider "Points sous le zoom 11 justes ?"
  step "Cliquer un tracé : il s'ouvre (?r= dans l'adresse), souligné d'un contour noir sous ses couleurs."
  step "Sur des tracés superposés, la plus contraignante s'ouvre (fermeture avant feux, avant déviation)."
  valider "Contour noir de la restriction ouverte, et priorité au clic, justes ?"
  step "Activer Permis : les deux couches restent lisibles ensemble."
  valider "Carte lisible avec Permis actif (sinon : revoir la palette) ?"
  suite
}

# ── 6 ─────────────────────────────────────────────────────────────────────
etape_bureau() {
  [[ -s "$TRAVAIL/communes.tsv" ]] || releve
  apercu_pret
  local chargee vide
  chargee=$(sed -n '1s/\t.*//p' "$TRAVAIL/communes.tsv")
  vide=$(sed -n '2s/\t.*//p' "$TRAVAIL/communes.tsv")
  say "Sur bureau (fenêtre large)."
  say ""
  open_url "$LOCAL/"
  step "Volet Routes : puces par sorte, En cours / À venir ; la liste suit la zone visible quand on bouge la carte ;"
  step "en cours par fin la plus proche, puis à venir par jour de début. Les puces filtrent aussi la carte."
  valider "Volet Routes juste sur bureau ?"
  step "Cliquer une restriction (carte ou volet) : l'aperçu (sorte, nom, période, horaires) ; « Voir la fiche › »"
  step "ouvre sa fiche."
  valider "Aperçu et « Voir la fiche › » justes sur bureau ?"
  step "Fil cantonal : une entrée par restriction (déviations comprises), au jour de son début, « À venir » si future."
  valider "Routes dans le fil justes ?"
  say ""
  open_url "$LOCAL/commune/$chargee"
  step "$chargee, onglet Routes : ses restrictions, et l'encadré des limites de la source (routes cantonales)."
  step "En ouvrir une : la fiche (sorte, nom, route en clair, période, horaires, remarque, communes traversées),"
  step "fil d'Ariane « Restriction de circulation », titre « Restriction de circulation – … – Vigie Vaud »."
  valider "Onglet Routes et fiche d'une restriction justes sur bureau ?"
  open_url "$LOCAL/commune/$vide"
  step "$vide, onglet Routes : aucune restriction, et le constat de l'onglet vide."
  valider "Onglet Routes vide juste ?"
  suite
}

# ── 7 ─────────────────────────────────────────────────────────────────────
etape_mobile() {
  [[ -s "$TRAVAIL/communes.tsv" ]] || releve
  apercu_pret
  local chargee; chargee=$(sed -n '1s/\t.*//p' "$TRAVAIL/communes.tsv")
  say "Sur mobile : outils de développement du navigateur, vue responsive à 375 px de large."
  say "(Un téléphone n'atteint pas localhost ; la vue responsive suffit, le site en ligne se revoit à l'étape 11.)"
  say ""
  open_url "$LOCAL/"
  step "Barre Carte · Fil · Couches · Fiche ; volet Routes (puces, liste de la zone visible) depuis Couches."
