# ── 8 ─────────────────────────────────────────────────────────────────────
etape_heures() {
  [[ -f "$TRAVAIL/nuit.tsv" ]] || releve
  apercu_pret
  if [[ ! -s "$TRAVAIL/nuit.tsv" ]]; then
    warn "aucune fermeture de nuit (HEURE_DEBUT et HEURE_FIN remplies) dans la DGMR aujourd'hui"
    noter "À REPRENDRE · Heures réelles : aucune fermeture de nuit le $(date +%F)"
    note "Reprendre un autre jour : scripts/mise-en-ligne-j2.sh 8"
    suite; return
  fi
  say "Fermetures de nuit du jour ($(wc -l < "$TRAVAIL/nuit.tsv" | tr -d ' ')), la première est ouverte :"
  cut -f2 "$TRAVAIL/nuit.tsv" | head -n 5 | sed 's/^/  /'
  local url description horaires remarque
  IFS=$'\t' read -r url description horaires remarque < "$TRAVAIL/nuit.tsv"
  say ""
  say "${BOLD}${description}${RESET}"
  say "Le site doit écrire : ${BOLD}${horaires}${RESET}"
  [[ -n "$remarque" ]] && note "Remarque de la DGMR : $remarque"
  open_url "$url"
  open_url "$VD_RESTRICTIONS"
  step "La fiche sur l'aperçu dit bien la ligne ci-dessus (heures de Lausanne, sans décalage d'une ou deux heures)."
  step "Sur vd.ch, retrouver les mêmes travaux (nom, route) : mêmes jours, mêmes heures de nuit."
  note "La forme de la page vd.ch (carte, liste ou avis PDF) n'est pas décrite ici : chercher par le nom des travaux."
  valider "Heures de ${description%% ·*} identiques au site et à vd.ch ?"
  suite
}

# ── 9 ─────────────────────────────────────────────────────────────────────
etape_lien_mort() {
  apercu_pret
  say "Un ?r= d'une restriction que la DGMR ne publie plus : vue lors d'un relevé précédent, ou citée par la"
  say "recherche du 17 octobre. Nouveau relevé pour savoir lesquelles ont disparu."
  releve
  if [[ ! -s "$TRAVAIL/morts.tsv" ]]; then
    warn "aucune restriction disparue depuis les relevés précédents"
    noter "À REPRENDRE · Lien mort réel : aucune restriction levée le $(date +%F)"
    note "Le relevé du jour est gardé : reprendre dans un ou deux jours, scripts/mise-en-ligne-j2.sh 9"
    suite; return
  fi
  say ""
  say "Disparues ($(wc -l < "$TRAVAIL/morts.tsv" | tr -d ' ')) :"
  cut -f2 "$TRAVAIL/morts.tsv" | head -n 5 | sed 's/^/  /'
  local url description
  IFS=$'\t' read -r url description < "$TRAVAIL/morts.tsv"
  say ""
  open_url "$url"
  step "La fiche de la commune s'ouvre sur l'onglet Routes, avec « Cette restriction de circulation n'est plus"
  step "publiée par la DGMR : elle a pu être levée ou modifiée. » ; aucune erreur, la carte reste utilisable."
  valider "Lien mort de $description juste ?"
  suite
}

# ── 10 ────────────────────────────────────────────────────────────────────
etape_pages() {
  [[ -s "$TRAVAIL/communes.tsv" ]] || releve
  apercu_pret
  local chargee; chargee=$(sed -n '1s/\t.*//p' "$TRAVAIL/communes.tsv")
  open_url "$LOCAL/a-propos"
  step "À propos : les Routes, lues en direct par le navigateur sur ogc.vd.ch, « Source : Géodonnées Etat de Vaud »."
  valider "À propos juste ?"
  open_url "$LOCAL/couverture"
  step "Couverture : colonne Routes (tout le canton, sans grisage) ; ligne « Limites » de la source DGMR :"
  step "« surtout les routes cantonales ; les routes communales n'y figurent pas toujours »."
  valider "Couverture (colonne Routes, ligne « Limites ») juste ?"
  open_url "$LOCAL/protection-des-donnees"
  step "Protection des données : ogc.vd.ch nommé pour les restrictions de circulation aussi."
  valider "Protection des données juste ?"
  say ""
  say "<head> de /commune/$chargee :"
  local tete
  tete=$(curl -fsS "$LOCAL/commune/$chargee" \
    | grep -oE '<title>[^<]*</title>|<meta (property="og:[a-z:]+"|name="(description|twitter:[a-z]+)")[^>]*>' || true)
  if [[ -z "$tete" ]]; then
    warn "ni titre ni balise d'aperçu trouvés"
  else
    printf '%s\n' "$tete" | sed 's/^/  /'
    if grep -q "restrictions de circulation en cours et à venir" <<<"$tete"; then
      ok "la description nomme les restrictions de circulation"
    else
      warn "la description ne nomme pas les restrictions de circulation"
    fi
  fi
  valider "Le <head> d'une commune est juste ?"
  suite
}

# ── 11 ────────────────────────────────────────────────────────────────────
etape_publication() {
  if grep -q "À REPRENDRE" "$NOTES" 2>/dev/null; then
    warn "des points sont notés à reprendre :"
    grep "À REPRENDRE" "$NOTES" | sed 's/^/  /'
  fi
  say ""
  say "La publication construit le site depuis main et le déploie sur Pages : $SITE"
  gh run list -R "$REPO_CODE" --workflow publier.yml -L 1 | sed 's/^/  Dernière : /' || true
  if ! confirm "Lancer la publication du site maintenant ?"; then
    warn "site non publié"
    noter "Publication non lancée"
    suite; return
  fi
  local avant id="" i
  avant=$(gh run list -R "$REPO_CODE" --workflow publier.yml -L 1 --json databaseId -q '.[0].databaseId // ""')
  lancer gh workflow run publier.yml -R "$REPO_CODE" --ref main
  for i in {1..30}; do
    id=$(gh run list -R "$REPO_CODE" --workflow publier.yml -L 1 --json databaseId -q '.[0].databaseId // ""')
    [[ -n "$id" && "$id" != "$avant" ]] && break
    id=""; sleep 2
  done
  [[ -n "$id" ]] || arreter "le passage de la publication n'apparaît pas : https://github.com/$REPO_CODE/actions"
  gh run watch "$id" -R "$REPO_CODE" --exit-status \
    || arreter "la publication a échoué : gh run view $id -R $REPO_CODE --log-failed"
  noter "Site publié : passage $id"
  say ""
  local chargee; chargee=$(sed -n '1s/\t.*//p' "$TRAVAIL/communes.tsv" 2>/dev/null || true)
  if [[ -n "$chargee" ]]; then
    if curl -fsS "$SITE/commune/$chargee" | grep -q "restrictions de circulation"; then
      ok "$SITE/commune/$chargee nomme les restrictions de circulation"
    else
      warn "$SITE/commune/$chargee ne nomme pas encore les Routes (Pages peut mettre une minute)"
    fi
  fi
  open_url "$SITE/"
  step "En ligne, sur bureau et sur un vrai téléphone : la couche Routes, des restrictions sur la carte, une fiche."
  valider "Le site en ligne montre les Routes ?"
  suite
}

# ── 12 ────────────────────────────────────────────────────────────────────
etat_sonde() {
  _clear
  printf '\n%s%s▸ Suivi de la sonde DGMR · %s · depuis %s%s\n\n' "$BOLD" "$BLUE" "$(date '+%F %R')" \
    "$(cat "$TRAVAIL/sonde-debut")" "$RESET"
  say "Source dgmr-restrictions (etat-sources.json du dépôt de données) :"
  curl -fsS "$PAGES_DONNEES/etat-sources.json" | python3 -c '
import json, sys
s = json.load(sys.stdin)["sources"].get("dgmr-restrictions")
print("  ⚠ absente" if s is None else "\n".join(f"  {k:<20} {v}" for k, v in s.items()))
' || warn "lecture impossible"
  say ""
  say "Derniers passages du cron :"
  gh run list -R "$REPO_DONNEES" -L 6 | sed 's/^/  /' || true
  say ""
  say "Issues panne-source (ouvertes et fermées) :"
  gh issue list -R "$REPO_DONNEES" --label panne-source --state all -L 5 \
    --json number,state,createdAt,title -q '.[] | "  #\(.number) \(.state) \(.createdAt) \(.title)"' || true
}

etape_sonde() {
  [[ -f "$TRAVAIL/sonde-debut" ]] || date '+%F %R' > "$TRAVAIL/sonde-debut"
  say "La sonde DGMR tourne à chaque passage du cron depuis la fusion de J2. À suivre sur une journée :"
  step "les passages du cron réussissent ;"
  step "dgmr-restrictions reste « disponible », sans échec consécutif ;"
  step "aucune issue panne-source ouverte à tort pour la DGMR (ni ouverte puis refermée)."
  note "Un passage en échec : gh run view <id> -R $REPO_DONNEES --log-failed"
  open_url "https://github.com/$REPO_DONNEES/actions"
  local reponse
  while true; do
    printf '\n'
    pause "Entrée : afficher l'état"
    etat_sonde
    printf '\n  %sEntrée : rafraîchir · ok : une journée suivie · q : revenir plus tard%s ' "$DIM" "$RESET"
    read -r reponse || true
    case "$reponse" in
      ok) break ;;
      q) note "Reprendre plus tard : scripts/mise-en-ligne-j2.sh $_STAGE_INDEX"; exit 0 ;;
    esac
  done
  valider "Sonde DGMR suivie une journée (depuis $(cat "$TRAVAIL/sonde-debut")), sans issue panne-source à tort ?"
  suite
}

# ── 13 ────────────────────────────────────────────────────────────────────
etape_bilan() {
  arreter_apercu
  say "Notes de la relecture ($NOTES) :"
  say ""
  sed 's/^/  /' "$NOTES" 2>/dev/null || note "(aucune note)"
  say ""
  if grep -q "À REPRENDRE" "$NOTES" 2>/dev/null; then
    warn "des points sont à reprendre : #$TICKET reste ouvert"
  fi
  if confirm "Publier ces notes en commentaire sur #$TICKET ?"; then
    { printf 'Mise en ligne de J2, notes du script `scripts/mise-en-ligne-j2.sh` :\n\n'; cat "$NOTES"; } \
      > "$TRAVAIL/commentaire.md"
    lancer gh issue comment "$TICKET" -R "$REPO_CODE" --body-file "$TRAVAIL/commentaire.md"
  fi
  note "Cocher les critères d'acceptation de #$TICKET et le fermer à la main, une fois tout vérifié."
  note "Le relevé du jour reste dans $TRAVAIL : le supprimer une fois #$TICKET fermé."
  open_url "https://github.com/$REPO_CODE/issues/$TICKET"
  suite
}

# ── Déroulé ───────────────────────────────────────────────────────────────

if [[ "${1:-}" == "liste" ]]; then
  for i in "${!ETAPES[@]}"; do printf '%2d · %s\n' $((i + 1)) "${ETAPES[$i]#*|}"; done
  exit 0
fi
DEBUT="${1:-1}"
if ! [[ "$DEBUT" =~ ^[0-9]+$ ]] || (( DEBUT < 1 || DEBUT > TOTAL_STAGES )); then
  printf 'usage : %s [étape 1-%d | liste]\n' "$0" "$TOTAL_STAGES" >&2
  exit 2
fi

banner "Mise en ligne de J2 (#$TICKET)"
_STAGE_INDEX=$((DEBUT - 1))
for entree in "${ETAPES[@]:DEBUT-1}"; do
  stage "${entree#*|}"
  "etape_${entree%%|*}"
done
finish
